exec python3 -c 'exec("import sys,math,json\nN=int(sys.argv[1])if len(sys.argv)>1 else 100000;lam=float(sys.argv[2])if len(sys.argv)>2 else .01;eps=1e-12\ndef D(n):\n b=[]\n while n>1:\n  n,r=divmod(n,257)\n  if not r:raise ValueError\n  b[:0]=[r-1]\n return bytes(b)\ndef G(b):\n n=1\n for v in b:n=n*257+v+1\n return n\ndef H(b):\n return-sum((b.count(v)/len(b))*math.log2(b.count(v)/len(b))for v in set(b))\nC=[]\nfor e in range(1,N+1):\n try:b=D(e)\n except ValueError:continue\n if b and b\"S\"in b and G(b)==e:C.append((e,b,H(b)+lam*len(b)))\nassert C,\"increase N to at least 341\"\nm=min(x[2]for x in C);W=[x for x in C if abs(x[2]-m)<=eps];beta=1.\nfor k in range(64):\n a=[-beta*(x[2]-m)for x in C];z=sum(math.exp(v)for v in a);p=[math.exp(v)/z for v in a];h=-sum(q*math.log2(q)for q in p if q)\n if h<=eps:break\n beta*=2\ne,b,j=min(W,key=lambda x:(len(x[1]),x[0]));unique=len(W)==1;r={\"candidate_rule\":\"C_N={e<=N:D(e) valid, S in D(e), G(D(e))=e}\",\"encoding\":\"base257 digits=byte+1\",\"self_rule\":\"U(e,SELF)=e\",\"constructor\":\"F_N(any)=argmin[H(symbols(D(e)))+lambda*len(D(e)),len,e]\",\"N\":N,\"candidates\":len(C),\"beta\":beta,\"H_N_bits\":h,\"limit_H_bits\":0 if unique else math.log2(len(W)),\"unique\":unique,\"prototype\":{\"code\":e,\"program_hex\":b.hex(),\"SELF\":e},\"fixed_point\":unique and e==G(b),\"scope\":\"finite-stage computable approximation; N->infinity is a limit definition, not a halting oracle\"}\nprint(json.dumps(r,separators=(\",\",\":\")))\n")' "$@"
